const cfg = { proxy: "127.0.0.1", port: 7897 };
const js = [
  "const http=require('http');",
  "const cfg=" + JSON.stringify(cfg) + ";",
  "const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36';",
  "const u='https://www.reddit.com/r/beermoney/top/.rss?t=year';",
  "const pu=new URL(u);",
  "http.get({host:cfg.proxy,port:cfg.port,path:u,headers:{Host:pu.host,'User-Agent':UA,'Accept':'application/rss+xml'}},function(res){",
  "  const c=[];res.on('data',function(d){c.push(d)});",
  "  res.on('end',function(){",
  "    const xml=Buffer.concat(c).toString('utf8');",
  "    console.log('STATUS',res.statusCode,'LEN',xml.length);",
  "    console.log('HEAD:', xml.substring(0,800).replace(/\\s+/g,' '));",
  "    console.log('ENTRY COUNT:', (xml.match(/<entry>/g)||[]).length);",
  "    console.log('ITEM COUNT:', (xml.match(/<item>/g)||[]).length);",
  "  });",
  "}).on('error',function(e){console.log('ERR',e.message)});",
].join("\n");
await tools.write({ file_path: "C:/Users/jjq21/AppData/Local/Temp/ofm-rss3.cjs", content: js });
const f = "C:/Users/jjq21/AppData/Local/Temp/ofm-rss3.cjs";
